export interface DataTableColumnHeaderProps<TData, TValue> {
  column: Column<TData, TValue>;
  title: ReactNode;
  className?: string;
}

export function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) {
    return (
      <span className={cn('block truncate', className)}>{title}</span>
    );
  }

  const sort = column.getIsSorted();

  return (
    <button
      type="button"
      data-slot="data-table-column-header"
      data-sort={sort || undefined}
      onClick={column.getToggleSortingHandler()}
      className={cn(
        'group/sort inline-flex max-w-full cursor-pointer items-center gap-1 font-normal text-grayscale-opacity-800 transition-colors hover:text-grayscale-opacity-900 focus-visible:shadow-focus-primary focus-visible:outline-none',
        className,
      )}
    >
      <span className="truncate">{title}</span>
      {/* Unsorted arrows wait for the pointer over the th (group/th) or
          keyboard focus. A sorted column keeps its arrow on screen. */}
      <span
        aria-hidden="true"
        className={cn(
          'inline-flex size-4 shrink-0 flex-col items-center justify-center',
          !sort &&
            'opacity-0 group-hover/th:opacity-100 group-focus-visible/sort:opacity-100',
        )}
      >
        <CaretUpSolidIcon
          className={cn(
            '-mb-1 size-3.75 shrink-0',
            sort === 'asc'
              ? 'text-grayscale-opacity-800'
              : 'text-grayscale-opacity-400',
          )}
        />
        <CaretDownSolidIcon
          className={cn(
            '-mt-1 size-3.75 shrink-0',
            sort === 'desc'
              ? 'text-grayscale-opacity-800'
              : 'text-grayscale-opacity-400',
          )}
        />
      </span>
    </button>
  );
}

import { Checkbox } from '@/components/checkbox/Checkbox';
import { TableCell, TableRow } from '@/components/table/Table';
import { CaretDownSolidIcon } from '@/icons/CaretDownSolidIcon';
import { cn } from '@/lib/utils';

/**
 * The bar itself is h-9 (36px) or h-11 (44px). A table cell treats
 * that as a minimum and adds its 1px bottom border, so the rows
 * occupy 37px and 45px. Each deeper group sticks under the ones above it.
 */
const ROOT_GROUP_HEIGHT = 37;
const NESTED_GROUP_HEIGHT = 45;

/** Empty track before a nested group. One track per ancestor. */
export const NESTED_GUTTER = 40;

export function groupStickyTop(depth: number): number {
  if (depth <= 0) return 0;
  return ROOT_GROUP_HEIGHT + (depth - 1) * NESTED_GROUP_HEIGHT;
}

/** Column header sticks just under the group it belongs to. */
export function columnHeaderStickyTop(depth: number): number {
  return groupStickyTop(depth + 1);
}

function groupChrome(depth: number) {
  const root = depth === 0;
  return {
    row: root
      ? 'sticky z-30 bg-grayscale-100 hover:bg-grayscale-200'
      : 'sticky z-20 bg-background hover:bg-grayscale-opacity-100',
    bar: root ? 'h-9 bg-grayscale-100' : 'h-11 bg-background',
    title: root
      ? 'font-medium text-grayscale-opacity-900'
      : 'font-medium text-grayscale-opacity-800',
  };
}

/**
 * Vertical spine for a second-level group. `branch` turns off toward the title.
 * The last group keeps only that turn. The line does not run on through its table.
 */
export function NestingRail({
  branch = false,
  continued = true,
}: {
  branch?: boolean;
  continued?: boolean;
}) {
  if (!branch && !continued) return null;

  return (
    <>
      {continued ? (
        <span
          aria-hidden="true"
          className="pointer-events-none absolute -top-px -bottom-px left-[calc(100%-12px)] w-px bg-border-overlap"
        />
      ) : null}
      {branch ? (
        <span
          aria-hidden="true"
          className="pointer-events-none absolute top-0 right-0 h-[22px] w-3 rounded-bl-[8px] border-b border-l border-border-overlap"
        />
      ) : null}
    </>
  );
}

/**
 * One cell per nesting level. `rails[i]` keeps that ancestor's line
 * going. The branch sits on the innermost cell.
 */
export function GutterCells({
  rails,
  branch = false,
  className,
}: {
  rails: boolean[];
  branch?: boolean;
  className?: string;
}) {
  return rails.map((line, index) => (
    <td
      key={index}
      className={cn('sticky z-10 border-0 bg-background p-0', className)}
      style={{
        width: NESTED_GUTTER,
        left: index * NESTED_GUTTER,
      }}
    >
      <NestingRail
        branch={branch && index === rails.length - 1}
        continued={line}
      />
    </td>
  ));
}

export function GroupHeaderRow({
  depth,
  title,
  open,
  columnCount,
  viewportWidth,
  lineInset = 0,
  rails = [],
  padEnd = false,
  bottomBorder = true,
  selection,
  onToggle,
}: {
  depth: number;
  title: string;
  open: boolean;
  columnCount: number;
  viewportWidth: number;
  /** Bottom border starts here, so it does not run into the left edge. */
  lineInset?: number;
  /**
   * Ancestor lines, outer first. The last entry is this group's own
   * line to the next sibling.
   */
  rails?: boolean[];
  /** Space after this header, before the next project. Hidden when the parent collapses. */
  padEnd?: boolean;
  /** Skip the bottom line when it would sit on the next header's top line. */
  bottomBorder?: boolean;
  /** Selects every task under this outermost group. */
  selection?: {
    label: string;
    checked: boolean;
    indeterminate: boolean;
    disabled?: boolean;
    onCheckedChange: (checked: boolean) => void;
  };
  onToggle: () => void;
}) {
  const level = groupChrome(depth);
  const gutter = rails.length * NESTED_GUTTER;
  const buttonWidth =
    viewportWidth > gutter ? viewportWidth - gutter : undefined;

  return (
    <TableRow
      data-slot="data-table-group-row"
      data-depth={depth}
      className={cn('cursor-pointer border-b-0', level.row)}
      style={{ top: groupStickyTop(depth) }}
    >
      {rails.length > 0 ? (
        <GutterCells rails={rails} branch className="z-20" />
      ) : null}
      <TableCell
        colSpan={columnCount}
        className={cn(
          // [role=checkbox] matches TableCell's own `[&:has([role=checkbox])]:px-3`,
          // so tailwind-merge drops it. A data-slot selector would leave both.
          'border-r-0 border-b border-transparent p-0 [&:has([role=checkbox])]:px-0',
          level.bar,
          padEnd && 'pb-3',
        )}
      >
        {selection ? (
          <div
            className={cn(
              'sticky flex w-full items-center',
              level.bar,
              level.title,
            )}
            style={{
              left: gutter,
              width: buttonWidth,
            }}
          >
            <span
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-0 top-0 h-px bg-grayscale-opacity-300"
            />
            {bottomBorder && gutter === 0 ? (
              <span
                aria-hidden="true"
                className="pointer-events-none absolute right-0 -bottom-px h-px bg-grayscale-opacity-300"
                style={{ left: lineInset }}
              />
            ) : null}
            <span className="flex w-10 shrink-0 items-center justify-center">
              <Checkbox
                aria-label={selection.label}
                checked={selection.checked}
                indeterminate={selection.indeterminate}
                disabled={selection.disabled}
                onCheckedChange={(value) =>
                  selection.onCheckedChange(Boolean(value))
                }
              />
            </span>
            <button
              type="button"
              aria-expanded={open}
              onClick={onToggle}
              className={cn(
                'flex min-w-0 flex-1 items-center gap-2 pr-4 pl-2 text-left text-sm',
                level.bar,
                level.title,
              )}
            >
              <CaretDownSolidIcon
                className={cn(
                  'size-5 shrink-0 text-grayscale-opacity-700 transition-transform',
                  !open && '-rotate-90',
                )}
              />
              <span className="truncate">{title}</span>
            </button>
          </div>
        ) : (
          <button
            type="button"
            aria-expanded={open}
            onClick={onToggle}
            className={cn(
              'sticky flex w-full items-center gap-2 px-4 text-left text-sm',
              level.bar,
              level.title,
              rails.length === 0 && depth > 0 && 'pl-10',
            )}
            style={{
              left: gutter,
              width: buttonWidth,
            }}
          >
            {depth === 0 ? (
              <span
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 top-0 h-px bg-grayscale-opacity-300"
              />
            ) : null}
            {bottomBorder && gutter === 0 ? (
              <span
                aria-hidden="true"
                className="pointer-events-none absolute right-0 -bottom-px h-px bg-grayscale-opacity-300"
                style={{ left: lineInset }}
              />
            ) : null}
            {rails.length === 0 && depth > 0 ? (
              <span
                aria-hidden="true"
                className="pointer-events-none absolute top-0 left-4 h-[22px] w-3 rounded-bl-[8px] border-b border-l border-border-overlap"
              />
            ) : null}
            <CaretDownSolidIcon
              className={cn(
                'size-5 shrink-0 text-grayscale-opacity-700 transition-transform',
                !open && '-rotate-90',
              )}
            />
            <span className="truncate">{title}</span>
          </button>
        )}
      </TableCell>
    </TableRow>
  );
}

import type { Column, Table } from '@tanstack/react-table';
import type { CSSProperties } from 'react';

/** Header order: left pins, unpinned center, then right pins. */
export function getLeafColumnsInDisplayOrder<TData>(
  table: Table<TData>,
) {
  return [
    ...table.getLeftVisibleLeafColumns(),
    ...table.getCenterVisibleLeafColumns(),
    ...table.getRightVisibleLeafColumns(),
  ];
}

const PIN_START_SHADOW = '--data-table-pin-start-shadow';
const PIN_END_SHADOW = '--data-table-pin-end-shadow';

/**
 * Sticky offset for a pinned column. Resizing runs in `onChange` mode,
 * which re-renders on every move, so a pixel offset stays in sync with
 * layout. One left pin (select) sits at 0; one right pin (actions) sits at 0.
 */
export function getPinningStyles<TData>(
  column: Column<TData>,
  zIndex = 1,
): CSSProperties {
  const pinned = column.getIsPinned();
  if (!pinned) return {};

  const isLeft = pinned === 'left';
  // The pinned edge that columns scroll under. The table sets the shadow
  // variables only while content is hidden on that side.
  const startEdge = isLeft && column.getIsLastColumn('left');
  const endEdge = !isLeft && column.getIsFirstColumn('right');

  return {
    position: 'sticky',
    left: isLeft ? `${column.getStart('left')}px` : undefined,
    right: isLeft ? undefined : `${column.getAfter('right')}px`,
    width: column.getSize(),
    zIndex,
    // The end edge line stays on the pinned column while other columns
    // scroll under it. The column beside it does not also draw this edge.
    boxShadow: endEdge
      ? `inset 1px 0 0 var(--grayscale-opacity-300), var(${PIN_END_SHADOW}, 0 0 #0000)`
      : startEdge
        ? `var(${PIN_START_SHADOW}, 0 0 #0000)`
        : undefined,
    // Keeps each cell's shadow on its outer side, so the cells of one
    // column read as one shadow with no seams between rows.
    clipPath: endEdge
      ? 'inset(0 0 0 -16px)'
      : startEdge
        ? 'inset(0 -16px 0 0)'
        : undefined,
  };
}

/**
 * Turns on the pinned-column shadows (Figma `Depth1 點綴`) on the side
 * where columns are scrolled out of view.
 */
export function pinShadowVars(edges: {
  start: boolean;
  end: boolean;
}): CSSProperties {
  return {
    ...(edges.start
      ? { [PIN_START_SHADOW]: 'var(--shadow-accent)' }
      : {}),
    ...(edges.end
      ? { [PIN_END_SHADOW]: 'var(--shadow-accent)' }
      : {}),
  } as CSSProperties;
}

'use client';

import { Avatar } from '@/components/avatar/Avatar';
import { Calendar } from '@/components/calendar/Calendar';
