type AvatarColor = ComponentProps<typeof Avatar>['color'];

export type PersonOption = {
  id: string;
  name: string;
  color: AvatarColor;
};
export type TagOption = { id: string; label: string };

/**
 * A cell that opens an editor in a popover. The cell shows `children`;
 * `editor` renders the popover body and gets `close` for editors that
 * commit on one pick.
 */
export function PopoverEditCell({
  label,
  children,
  editor,
}: {
  /** Accessible name of the cell button, e.g. `狀態 待覆核`. */
  label: string;
  children: ReactNode;
  editor: (close: () => void) => ReactNode;
}) {
  const [open, setOpen] = useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        type="button"
        aria-label={label}
        data-slot="popover-edit-trigger"
        className="inline-flex h-11 w-full min-w-0 items-center rounded-none border border-transparent px-3 text-left outline-none focus-visible:border-primary-500 data-[popup-open]:border-primary-500"
      >
        {children}
      </PopoverTrigger>
      <PopoverContent
        data-slot="popover-edit-content"
        className="w-auto p-1.5"
        align="start"
      >
        {editor(() => setOpen(false))}
      </PopoverContent>
    </Popover>
  );
}

function OptionCheck({ checked }: { checked: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        'grid size-4 shrink-0 place-content-center rounded-xs border border-grayscale-opacity-300 bg-background text-white transition-colors duration-200',
        checked && 'border-primary-500 bg-primary-500',
      )}
    >
      {checked ? (
        <CheckSolidIcon className="size-4 shrink-0" />
      ) : null}
    </span>
  );
}

const OPTION =
  'flex w-full cursor-pointer items-center gap-2 rounded px-2 py-1.5 text-left text-sm text-grayscale-opacity-800 outline-none select-none hover:bg-grayscale-opacity-150 focus-visible:bg-grayscale-opacity-150';

function toggle(value: readonly string[], id: string) {
  return value.includes(id)
    ? value.filter((item) => item !== id)
    : [...value, id];
}

/** Several people. Stays open; every click commits. */
export function PeopleEditor({
  value,
  options,
  onCommit,
}: {
  value: readonly string[];
  options: readonly PersonOption[];
  onCommit: (next: string[]) => void;
}) {
  return (
    <ul
      role="listbox"
      aria-multiselectable="true"
      className="flex w-56 flex-col gap-0.5"
    >
      {options.map((person) => {
        const checked = value.includes(person.id);
        return (
          <li key={person.id}>
            <button
              type="button"
              role="option"
              aria-selected={checked}
              onClick={() => onCommit(toggle(value, person.id))}
              className={OPTION}
            >
              <OptionCheck checked={checked} />
              <Avatar
                size="xs"
                name={person.name}
                fallback={person.name.slice(0, 1)}
                color={person.color}
              />
              {person.name}
            </button>
          </li>
        );
      })}
    </ul>
  );
}

/** Several tags. Stays open; every click commits. */
export function TagsEditor({
  value,
  options,
  onCommit,
}: {
  value: readonly string[];
  options: readonly TagOption[];
  onCommit: (next: string[]) => void;
}) {
  return (
    <ul
      role="listbox"
      aria-multiselectable="true"
      className="flex w-56 flex-col gap-0.5"
    >
      {options.map((tag) => {
        const checked = value.includes(tag.id);
        return (
          <li key={tag.id}>
            <button
              type="button"
              role="option"
              aria-selected={checked}
              onClick={() => onCommit(toggle(value, tag.id))}
              className={OPTION}
            >
              <OptionCheck checked={checked} />
              <Tag color="default">{tag.label}</Tag>
            </button>
          </li>
        );
      })}
    </ul>
  );
}

function formatDate(date: Date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}/${m}/${d}`;
}

/** One date, as YYYY/MM/DD. Picking the selected day again clears it. */
export function DateEditor({
  value,
  onCommit,
}: {
  value: string;
  onCommit: (next: string) => void;
}) {
  const selected = value ? new Date(value) : undefined;
  return (
    <Calendar
      mode="single"
      selected={selected}
      defaultMonth={selected}
      onSelect={(date) => onCommit(date ? formatDate(date) : '')}
    />
  );
}

import { cn } from '@/lib/utils';
import type { Header } from '@tanstack/react-table';
import type { MouseEvent, TouchEvent } from 'react';

const NUDGE_STEP = 8;
const NUDGE_STEP_LARGE = 40;
const RAISED_Z = '60';
const TOUCH_MOVE_OPTS: AddEventListenerOptions = {
  capture: true,
  passive: false,
};
const TOUCH_END_OPTS: AddEventListenerOptions = { capture: true };

type Ghost = {
  startX: number;
  size: number;
  minSize: number;
  maxSize: number;
};

function pointerClientX(
  event: globalThis.MouseEvent | globalThis.TouchEvent,
) {
  if ('touches' in event) {
    // `touchend` has an empty `touches` list; the lifted finger is only in
    // `changedTouches`. TanStack's `onEnd(e.touches[0]?.clientX)` hits this.
    return (
      event.touches[0]?.clientX ?? event.changedTouches[0]?.clientX
    );
  }
  return event.clientX;
}

function clampedGhostWidth(ghost: Ghost, clientX: number) {
  return Math.min(
    Math.max(ghost.size + clientX - ghost.startX, ghost.minSize),
    ghost.maxSize,
  );
}

/**
 * The drag guide runs from the header down through the body, so its height
 * cannot come from the `th` it lives in. Measure the scroll container once per
 * drag and hand the value to CSS.
 *
 * Measuring (instead of using a huge value) keeps the guide from adding
 * scrollable overflow, and keeping it inside the `th` means a pinned column's
 * guide inherits that cell's sticky offset for free.
 *
 * This table repeats the header row in every innermost group, and
 * those later rows are sticky with a z-index, so a single segment drawn from
 * the grabbed handle gets painted over and the line comes out broken. Every
 * copy of the column therefore draws its own segment from its own row down to
 * the end of the content; overlapped, they read as one continuous line.
 *
 * In `onEnd` mode the guide has to track the pointer, and it does so
 * imperatively: a layout may memoize its rows and freeze them for the drag,
 * which would freeze a React-driven ghost offset along with them and leave
 * the drag with no feedback at all.
 */
function startResizeGuide(
  handle: HTMLElement,
  ghost: Ghost | null,
  onCommit?: (width: number) => void,
) {
  const container = handle.closest<HTMLElement>(
    '[data-slot="table-container"]',
  );
  if (!container) return;

  const { columnId } = handle.dataset;
  const containerTop = container.getBoundingClientRect().top;
  const guides = Array.from(
    container.querySelectorAll<HTMLElement>(
      '[data-slot="data-table-resize-handle"]',
    ),
  ).filter((guide) => guide.dataset.columnId === columnId);

  // Sticky group-title rows sit above the header rows and would clip the
  // segments, so the cells hosting a guide are lifted for the drag and put back
  // afterwards. `RAISED_Z` clears the highest layer the table uses (the
  // outer group title at z-30).
  const raised: { el: HTMLElement; zIndex: string }[] = [];
  const raise = (el: Element | null) => {
    if (!(el instanceof HTMLElement)) return;
    raised.push({ el, zIndex: el.style.zIndex });
    el.style.zIndex = RAISED_Z;
  };

  for (const guide of guides) {
    const top =
      guide.getBoundingClientRect().top -
      containerTop +
      container.scrollTop;
    guide.style.setProperty(
      '--table-resize-guide-height',
      `${container.scrollHeight - top}px`,
    );
    guide.dataset.guide = 'true';
    raise(guide.closest('th, td'));
    raise(guide.closest('tr'));
  }

  const track = (
    event: globalThis.MouseEvent | globalThis.TouchEvent,
  ) => {
    if (!ghost) return;
    const clientX = pointerClientX(event);
    if (clientX === undefined) return;
    const next = clampedGhostWidth(ghost, clientX);
    for (const guide of guides) {
      guide.style.transform = `translateX(${next - ghost.size}px)`;
    }
  };

  const clear = () => {
    for (const guide of guides) {
      delete guide.dataset.guide;
      guide.style.removeProperty('--table-resize-guide-height');
      guide.style.removeProperty('transform');
    }
    for (const { el, zIndex } of raised) {
      el.style.zIndex = zIndex;
    }
    window.removeEventListener('mousemove', track);
    window.removeEventListener('mouseup', clear);
    window.removeEventListener('touchmove', track, TOUCH_MOVE_OPTS);
    window.removeEventListener(
      'touchend',
      onTouchEnd,
      TOUCH_END_OPTS,
    );
  };

  const onTouchEnd = (event: globalThis.TouchEvent) => {
    const clientX = pointerClientX(event);
    if (ghost && onCommit && clientX !== undefined) {
      onCommit(clampedGhostWidth(ghost, clientX));
    }
    clear();
  };

  if (ghost) {
    window.addEventListener('mousemove', track);
    // TanStack stopPropagates touchmove/touchend on `document`, so window
    // bubble never runs; capture on window sees the event first.
    window.addEventListener('touchmove', track, TOUCH_MOVE_OPTS);
  }
  window.addEventListener('mouseup', clear);
  window.addEventListener('touchend', onTouchEnd, TOUCH_END_OPTS);
}

export interface ResizeHandleProps<TData, TValue> {
  header: Header<TData, TValue>;
  /** Accessible name. Defaults to the column id. */
  label?: string;
  className?: string;
}

/**
 * Drag target that sits on the right edge of a `TableHead`.
 *
 * - pointer / touch drag resizes the column
 * - double click or `Home` resets it to the column's `size`
 * - `ArrowLeft` / `ArrowRight` nudge by 8px (40px with `Shift`)
 *
 * With `columnResizeMode: 'onEnd'` the guide follows the pointer and the column
 * only commits on release.
 */
export function ResizeHandle<TData, TValue>({
  header,
  label,
  className,
}: ResizeHandleProps<TData, TValue>) {
  const { column } = header;
  const { table } = header.getContext();

  if (!column.getCanResize()) {
    return null;
  }

  const isResizing = column.getIsResizing();
  const minSize =
    column.columnDef.minSize ??
    table.options.defaultColumn?.minSize ??
    20;
  const maxSize =
    column.columnDef.maxSize ?? table.options.defaultColumn?.maxSize;

  const resize = (delta: number) => {
    const next = Math.min(
      Math.max(column.getSize() + delta, minSize),
      maxSize ?? Number.MAX_SAFE_INTEGER,
    );
    table.setColumnSizing((sizing) => ({
      ...sizing,
      [column.id]: next,
    }));
  };

  const startDrag = (
    event: MouseEvent<HTMLDivElement> | TouchEvent<HTMLDivElement>,
  ) => {
    // Without this the drag selects the header text it passes over.
    if (event.type === 'mousedown') event.preventDefault();
    const startX =
      'touches' in event ? event.touches[0]?.clientX : event.clientX;
    // In `onEnd` mode the column stays put during the drag, so the guide
    // itself moves to show where the edge will land.
    const ghost =
      table.options.columnResizeMode === 'onEnd' &&
      startX !== undefined
        ? {
            startX,
            size: column.getSize(),
            minSize,
            maxSize: maxSize ?? Number.MAX_SAFE_INTEGER,
          }
        : null;
    startResizeGuide(event.currentTarget, ghost, (width) => {
      table.setColumnSizing((sizing) => ({
        ...sizing,
        [column.id]: width,
      }));
    });
    header.getResizeHandler()(event);
  };

  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-label={label ?? `Resize ${column.id} column`}
      aria-valuenow={column.getSize()}
      aria-valuemin={minSize}
      aria-valuemax={maxSize}
      tabIndex={0}
      data-slot="data-table-resize-handle"
      data-column-id={column.id}
      data-resizing={isResizing || undefined}
      onMouseDown={startDrag}
      onTouchStart={startDrag}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => {
        event.stopPropagation();
        column.resetSize();
      }}
      onKeyDown={(event) => {
        if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
          event.preventDefault();
          const step = event.shiftKey ? NUDGE_STEP_LARGE : NUDGE_STEP;
          resize(event.key === 'ArrowLeft' ? -step : step);
          return;
        }
        if (event.key === 'Home') {
          event.preventDefault();
          column.resetSize();
        }
      }}
      className={cn(
        'absolute inset-y-0 right-0 z-30 w-2 cursor-col-resize touch-none select-none',
        'after:absolute after:top-0 after:right-0 after:h-full after:w-px after:bg-transparent after:content-[""]',
        // Hover shows nothing but the col-resize cursor; the only blue line is
        // the drag guide.
        'focus-visible:outline-none focus-visible:after:w-0.5 focus-visible:after:bg-primary-500',
        // While dragging, the grabbed handle becomes a guide line that runs
        // down the whole body.
        'data-[guide]:after:h-[var(--table-resize-guide-height,100%)] data-[guide]:after:w-0.5 data-[guide]:after:bg-primary-500',
        className,
      )}
    />
  );
}

'use client';

import { Checkbox } from '@/components/checkbox/Checkbox';
import type {
  ColumnDef,
  RowSelectionState,
  Table,
} from '@tanstack/react-table';
import { createContext, useContext } from 'react';
import { RowActionsMenu } from './action-bar';

/** Rows a repeated header checkbox may select. Flat tables leave this empty. */
export type SelectionScope = {
  label: string;
  ids: readonly string[];
};

export const SelectionScopeContext =
  createContext<SelectionScope | null>(null);

export function selectionFlags(
  ids: readonly string[],
  isSelected: (id: string) => boolean,
) {
  let selected = 0;
  for (const id of ids) {
    if (isSelected(id)) selected += 1;
  }
  return {
    checked: ids.length > 0 && selected === ids.length,
    indeterminate: selected > 0 && selected < ids.length,
  };
}

export function nextRowSelection(
  current: RowSelectionState,
  ids: readonly string[],
  selected: boolean,
): RowSelectionState {
  const next = { ...current };
  for (const id of ids) {
    if (selected) next[id] = true;
    else delete next[id];
  }
  return next;
}

function SelectAllCheckbox<TData>({
  table,
}: {
  table: Table<TData>;
}) {
  const scope = useContext(SelectionScopeContext);
  if (!scope) {
    return (
      <Checkbox
        aria-label="全選"
        checked={table.getIsAllPageRowsSelected()}
        indeterminate={table.getIsSomePageRowsSelected()}
        onCheckedChange={(value) =>
          table.toggleAllPageRowsSelected(Boolean(value))
        }
      />
    );
  }

  const flags = selectionFlags(scope.ids, (id) =>
    table.getRow(id).getIsSelected(),
  );

  return (
    <Checkbox
      aria-label={`全選 ${scope.label}`}
      checked={flags.checked}
      indeterminate={flags.indeterminate}
      disabled={scope.ids.length === 0}
      onCheckedChange={(value) =>
        table.setRowSelection(
          nextRowSelection(
            table.getState().rowSelection,
            scope.ids,
            Boolean(value),
          ),
        )
      }
    />
  );
}

/** Pinned left. Names each row checkbox after `rowLabel`. */
export function selectColumn<TData>(
  rowLabel: (row: TData) => string,
): ColumnDef<TData> {
  return {
    id: 'select',
    header: ({ table }) => <SelectAllCheckbox table={table} />,
    cell: ({ row }) => (
      <Checkbox
        aria-label={`選取 ${rowLabel(row.original)}`}
        checked={row.getIsSelected()}
        onCheckedChange={(value) =>
          row.toggleSelected(Boolean(value))
        }
      />
    ),
    size: 40,
    minSize: 40,
    maxSize: 40,
    enableSorting: false,
    enableHiding: false,
    enableResizing: false,
  };
}

/** Pinned right. The row menu; 刪除 removes the row. */
export function actionsColumn<TData>(): ColumnDef<TData> {
  return {
    id: 'actions',
    header: () => <span className="sr-only">操作</span>,
    // text icon-md is 1em (14px). The pinned cell pads 12px on each side.
    size: 38,
    minSize: 38,
    maxSize: 38,
    enableSorting: false,
    enableHiding: false,
    enableResizing: false,
    cell: ({ row, table }) => (
      <RowActionsMenu
        onDelete={() => table.options.meta?.removeRow(row.id)}
      />
    ),
  };
}

import { XmarkIcon } from '@/icons/XmarkIcon';
import { useLayoutEffect, useRef, useState } from 'react';

type Counts = { selected: number; total: number };

/**
 * Floats over the table while rows are selected. The zero-height
 * wrapper sits at the end of the card and sticks to the screen bottom,
 * so the bar stays 12px above whichever comes first: the card's bottom
 * edge or the bottom of the screen.
 *
 * It slides in like a toast. When the selection empties it keeps the
 * last counts on screen and unmounts after it has slid out.
 */
export function SelectionBar({
  label,
  selectedCount,
  totalCount,
  onSelectAll,
  onDelete,
  onClear,
}: {
  /** Name of the toolbar, e.g. 已選取的任務. */
  label: string;
  selectedCount: number;
  /** Rows the current search shows. */
  totalCount: number;
  onSelectAll: () => void;
  onDelete: () => void;
  onClear: () => void;
}) {
  const open = selectedCount > 0;
  const [shown, setShown] = useState<Counts | null>(
    open ? { selected: selectedCount, total: totalCount } : null,
  );
  const barRef = useRef<HTMLDivElement>(null);
  const deleteRef = useRef<HTMLButtonElement>(null);

  // While open, follow the live counts. While closing, keep the last
  // ones, so the bar does not read 已選擇 0 筆 on its way out.
  if (
    open &&
    (shown?.selected !== selectedCount || shown.total !== totalCount)
  ) {
    setShown({ selected: selectedCount, total: totalCount });
  }

  // The closed state rests at opacity 0. Once the exit animation ends,
  // the bar would otherwise show at full opacity for the frame before
  // React removes it.
  //
  // No exit animation to wait for (reduced motion, or no Web
  // Animations API): unmount right away instead of waiting for an
  // animationend that never comes. Only a CSS animation fires
  // animationend; a running transition does not count.
  useLayoutEffect(() => {
    if (open || !shown) return;
    const bar = barRef.current;
    const exiting =
      bar !== null &&
      typeof bar.getAnimations === 'function' &&
      typeof CSSAnimation !== 'undefined' &&
      bar
        .getAnimations()
        .some((animation) => animation instanceof CSSAnimation);
    if (!exiting) setShown(null);
  }, [open, shown]);

  if (!shown) return null;

  return (
    <div
      data-slot="data-table-selection-bar"
      className="pointer-events-none sticky bottom-0 z-40 h-0"
    >
      <div
        ref={barRef}
        role="toolbar"
        aria-label={label}
        data-state={open ? 'open' : 'closed'}
        inert={!open}
        onAnimationEnd={(event) => {
          if (!open && event.target === event.currentTarget) {
            setShown(null);
          }
        }}
        className="absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-10 rounded-lg bg-grayscale-opacity-900/85 py-3 pr-4 pl-6 text-sm leading-5 whitespace-nowrap text-background shadow-emphasis backdrop-blur-[4px] ease-out motion-safe:duration-300 data-[state=closed]:opacity-0 data-[state=open]:pointer-events-auto motion-safe:data-[state=closed]:animate-out motion-safe:data-[state=closed]:fade-out-0 motion-safe:data-[state=closed]:slide-out-to-bottom motion-safe:data-[state=open]:animate-in motion-safe:data-[state=open]:fade-in-0 motion-safe:data-[state=open]:slide-in-from-bottom"
      >
        <div className="flex items-center gap-4">
          <span role="status">
            已選擇{' '}
            <span className="font-medium text-info-400 dark:text-info-200">
              {shown.selected}
            </span>{' '}
            筆
          </span>
          {shown.selected < shown.total ? (
            <button
              type="button"
              onClick={() => {
                // Selecting everything removes this button. Keep focus
                // in the bar, on the next action.
                deleteRef.current?.focus();
                onSelectAll();
              }}
              className="cursor-pointer font-medium text-info-400 hover:underline dark:text-info-200 focus-visible:shadow-focus-primary focus-visible:outline-none"
            >
              全選 {shown.total} 筆
            </button>
          ) : null}
        </div>
        <div className="flex items-center gap-6">
          <button
            ref={deleteRef}
            type="button"
            onClick={onDelete}
            className="cursor-pointer font-medium text-destructive-400 hover:underline dark:text-destructive-300 focus-visible:shadow-focus-primary focus-visible:outline-none"
          >
            刪除
          </button>
          <span className="flex items-center border-l border-background/25 pl-4">
            <button
              type="button"
              aria-label="取消選取"
              onClick={onClear}
              className="flex size-5 cursor-pointer items-center justify-center text-current/85 hover:text-current focus-visible:shadow-focus-primary focus-visible:outline-none"
            >
              <XmarkIcon className="size-5" />
            </button>
          </span>
        </div>
      </div>
    </div>
  );
}
